 "cine_b2_k": "EN 1090-2 · EXC3",
 "cine_b2_h": "Grandi pezzi, zero compromessi.",
 "cine_b2_p": "Bracci, telai e parti portanti. Procedure approvate per ogni acciaio, dall'S235 allo Strenx 1100.",
