 "docs_lede": "Consulti o scarichi i nostri certificati dei sistemi di gestione qualità, ambiente, salute e sicurezza sul lavoro e saldatura, rilasciati da organismi accreditati.",
 "docs_stat_certs": "Certificati attivi",
 "docs_stat_exc": "Classe EN 1090-2",
 "docs_stat_3834": "Livello ISO 3834-2",
 "docs_stat_format": "Documento originale",
 "docs_intro_eyebrow": "Verificabilità",
 "docs_intro_h2": "Ogni certificato è il risultato di un processo di audit indipendente",
 "docs_intro_p": "Condividiamo tutti i nostri certificati in modo trasparente con clienti e auditor. I documenti sono in formato PDF originale e possono essere inseriti direttamente nei Suoi fascicoli di progetto.",
