 "docs_cta_h3": "Scopra di più sui nostri processi di qualità",
 "docs_cta_p": "Visiti la nostra pagina Qualità per informazioni dettagliate su tracciabilità, piani di ispezione e rigore documentale.",
 "docs_cta_btn": "Qualità e tracciabilità →",
 "sectors_h1": "I settori che<br/><span class=\"arc\">serviamo.</span>",
 "sectors_lede": "Dalle macchine movimento terra alle infrastrutture energetiche, dai recipienti in pressione al materiale ferroviario — una produzione conforme agli standard di ogni settore.",
 "sectors_s01_num": "// 01 · MACCHINARI",
 "sectors_s01_h2": "Macchinari e<br/><span class=\"arc\">macchine movimento terra.</span>",
 "sectors_s01_desc": "Fabbricazione di benne, telai e corpi macchina in HARDOX, Strenx e acciai ad alta resistenza. WPS specialistiche per materiali antiusura e ad alta resistenza.",
 "sectors_s02_num": "// 02 · CARPENTERIA STRUTTURALE",
 "sectors_s02_h2": "Carpenteria strutturale e<br/><span class=\"arc\">costruzioni industriali.</span>",
 "sectors_s02_desc": "Ponti, strutture di edifici industriali e vie di corsa per gru secondo EN 1090 EXC2/3.",
 "sectors_s03_num": "// 03 · PROCESSO E RECIPIENTI IN PRESSIONE",
 "sectors_s03_h2": "Recipienti in pressione e<br/><span class=\"arc\">apparecchiature di processo.</span>",
 "sectors_s03_desc": "Recipienti in pressione e serbatoi di processo secondo PED Cat. I–II. Saldature a piena penetrazione, CND al 100% e dichiarazione CE.",
 "sectors_s04_num": "// 04 · ENERGIA",
 "sectors_s04_h2": "Energia e<br/><span class=\"arc\">infrastrutture rinnovabili.</span>",
 "sectors_s04_desc": "Strutture per pannelli solari, staffe per eolico, telai per generatori. Sabbiatura Sa 2½ + verniciatura a doppio strato per una protezione di oltre 20 anni.",
 "sectors_s05_num": "// 05 · TRASPORTI E FERROVIARIO",
 "sectors_s05_h2": "Trasporti, sistemi ferroviari<br/>&amp; <span class=\"arc\">difesa.</span>",
 "sectors_s05_desc": "Strutture ferroviarie secondo EN 15085 CL1/CL2, fabbricazione di blindature in HARDOX per applicazioni nella difesa.",
 "sectors_cta_h2": "Richieda una valutazione su misura per il Suo progetto.",
 "sectors_cta_lede": "Entrare in nuovi ambiti è per noi un'opportunità di apprendimento. Ci parli del Suo progetto e lavoriamo insieme sullo standard di riferimento.",
