 "contact_side_h": "Perché ArmaWeld?",
 "home_svc_r1_name": "Carpenteria metallica saldata",
 "home_svc_r1_brief": "Da S235 a Strenx 1100, da S690QL e S960QL fino a HARDOX — produzione affidabile su ogni gruppo di acciai, inclusi inox e alluminio, con WPS approvate.",
 "home_svc_r2_name": "Taglio lamiera e lavorazione profilati",
 "home_svc_r2_brief": "Acciaio al carbonio, inox, Hardox, Strenx e alluminio — taglio a tolleranza controllata e preparazione pronta per la saldatura secondo disegno tecnico.",
 "home_svc_r3_name": "Piegatura e formatura",
 "home_svc_r3_brief": "Piegatura a V, formatura a U e calandratura — gestione programmata di angolo, raggio e accoppiamento in assemblaggio.",
 "home_svc_r4_name": "Assemblaggio meccanico e preparazione alla spedizione",
 "home_svc_r4_brief": "Sottoassiemi, registrazione delle coppie di serraggio e prove funzionali — imballaggio per la spedizione integrato nel piano di progetto.",
 "home_svc_r5_name": "CND e controlli non distruttivi",
 "home_svc_r5_brief": "4 metodi di controllo in-house, accettazione EN ISO 5817 livello B — ogni saldatura documentata, nessuna registrazione omessa.",
 "home_svc_r6_name": "Corpi macchina e benne per movimento terra",
 "home_svc_r6_brief": "Fabbricazione di benne, bowl, lame e corpi macchina in acciai antiusura — attrezzature per produzione in serie e controllo MT inclusi.",
 "home_svc_r7_name": "Costruzione di gru",
 "home_svc_r7_brief": "Fabbricazione di strutture per carroponti, gru a bandiera e monorotaia — consegnate con calcolo statico FEM e DoP CE.",
 "home_svc_r8_name": "Recipienti in pressione e serbatoi di processo",
 "home_svc_r8_brief": "Serbatoi di stoccaggio, reattori e scambiatori di calore secondo PED Cat. I–II — pacchetto documentale completo con RT + UT + dichiarazione CE.",
 "trace_step_label": "FASE",
 "trace_step1_title": "Ordine e ingegneria",
 "trace_step1_dur": "1–3 giorni",
 "trace_step1_chip": "FASE 01 · SOP.REV.ENG",
 "trace_step1_h": "Arriva il disegno tecnico, si apre l'ordine di lavoro.",
 "trace_step1_body": "I file DWG/DXF/PDF del cliente vengono esaminati dal nostro team di ingegneria. A ogni ordine di lavoro viene assegnato un numero di serie univoco e in questa fase si definiscono il percorso produttivo, la scelta delle WPS e il piano CND.",
 "trace_step1_d1": "Ordine di lavoro",
 "trace_step1_d2": "Disegno di produzione",
 "trace_step1_d3": "Scelta WPS",
 "trace_step1_d4": "Piano CND",
 "trace_step2_title": "Ingresso materiale e colata",
 "trace_step2_dur": "1 giorno",
 "trace_step2_chip": "FASE 02 · MAT.INCOMING",
 "trace_step2_h": "Numero di colata della lamiera registrato con certificato 3.1.",
 "trace_step2_body": "Lamiera S355 J2+N di Metalurji A.Ş.; colata A41E2 registrata con MTC-2026-4182 (EN 10204 3.1). Dopo VT e controllo dello spessore, la lamiera viene marcata con l'ordine di lavoro JOB-A142.",
 "trace_step2_d1": "Certificato del materiale",
 "trace_step2_d2": "Esame visivo",
 "trace_step2_d3": "Misura dello spessore",
 "trace_step2_d4": "Registrazione colata",
 "trace_step3_title": "Taglio e piegatura",
 "trace_step3_dur": "1–2 giorni",
 "trace_step3_chip": "FASE 03 · CUT.FORM",
 "trace_step3_h": "Taglio CNC, controllo tolleranze, piegatura.",
 "trace_step3_body": "Le lamiere vengono tagliate al plasma CNC o al laser secondo il DXF; i profilati vengono preparati con gli angoli appropriati. Le pieghe sono simulate ed eseguite all'angolo corretto. Ogni pezzo riporta fisicamente ordine di lavoro + numero di colata.",
 "trace_step3_d1": "Programma di taglio",
 "trace_step3_d2": "Rapporto dimensionale",
 "trace_step3_d3": "Controllo angolo di piega",
 "trace_step3_d4": "Etichetta del pezzo",
 "trace_step4_title": "Carpenteria saldata",
 "trace_step4_dur": "3–10 giorni",
 "trace_step4_chip": "FASE 04 · WELDING.ACTIVE",
 "trace_step4_h": "Saldatore certificato, WPS approvata.",
 "trace_step4_body": "La saldatura viene eseguita solo da saldatori certificati per quella procedura. Ogni cordone viene registrato digitalmente con codice saldatore, numero WPS, numero di passate e parametri filo/gas. Le temperature di preriscaldo e interpass sono monitorate in continuo.",
 "trace_step4_d1": "Patentino del saldatore",
 "trace_step4_d2": "WPS",
 "trace_step4_d3": "Registro saldature",
 "trace_step4_d4": "Temperatura interpass",
 "trace_step5_title": "CND / Ispezione",
 "trace_step5_dur": "1–3 giorni",
 "trace_step5_chip": "FASE 05 · NDT.INSPECT",
 "trace_step5_h": "Controlli non distruttivi: visivo, superficiale, volumetrico.",
 "trace_step5_body": "Secondo il piano CND: esame visivo (VT) al 100%, liquidi penetranti (PT) o particelle magnetiche (MT) sulle saldature critiche, ultrasuoni (UT) o radiografia (RT) per il controllo volumetrico. Rapporti redatti da personale di Livello II.",
 "trace_step5_d1": "Rapporto VT",
 "trace_step5_d2": "Rapporto PT/MT",
 "trace_step5_d3": "Rapporto UT",
 "trace_step5_d4": "Criteri di accettazione",
 "trace_step6_title": "Superficie e rivestimento",
 "trace_step6_dur": "1–3 giorni",
 "trace_step6_chip": "FASE 06 · SURFACE.COAT",
 "trace_step6_h": "Sabbiatura, primer, finitura — protezione C3/C4.",
 "trace_step6_body": "I pezzi vengono preparati al grado di sabbiatura Sa 2½; si applica un ciclo di verniciatura adeguato alla categoria di corrosività. Lo spessore del film secco (DFT) viene misurato e riportato a ogni mano.",
 "trace_step6_d1": "Grado di sabbiatura",
 "trace_step6_d2": "Ciclo di verniciatura",
 "trace_step6_d3": "Misura DFT",
 "trace_step6_d4": "Colore / Codice",
 "trace_step7_title": "Spedizione e dossier",
 "trace_step7_dur": "1 giorno",
 "trace_step7_chip": "FASE 07 · SHIP.DOSSIER",
 "trace_step7_h": "Prodotto + dossier documentale consegnati insieme.",
 "trace_step7_body": "Dopo l'ispezione finale il prodotto viene imballato. Un pacchetto documentale completo collegato all'ordine di lavoro — WPS, WPQR, patentini dei saldatori, certificati dei materiali, rapporti CND, registrazioni dimensionali e DFT, dichiarazione CE — viene consegnato in un unico fascicolo.",
 "trace_step7_d1": "Documento di trasporto",
 "trace_step7_d2": "Dossier documentale (pdf)",
 "trace_step7_d3": "CE / DoP",
 "trace_step7_d4": "Scheda di tracciamento QR",
 "home_cmp_mig_full": "Saldatura ad arco con filo continuo — gas inerte / attivo",
 "home_cmp_tig_full": "Saldatura ad arco con elettrodo di tungsteno — gas inerte",
 "home_cmp_earc_full": "Saldatura ad arco con elettrodo rivestito — SMAW",
 "home_cmp_mig_use": "Alto tasso di deposito, cordoni lunghi, produzione in serie, macchine movimento terra, strutture per gru e carpenteria strutturale — prima scelta.",
 "home_cmp_tig_use": "Pareti sottili, passate di radice precise, serbatoi e recipienti in pressione inox, applicazioni igieniche alimentari, saldature a vista — indispensabile.",
 "home_cmp_earc_use": "Condizioni di cantiere, esterni, cantieri esposti al vento e saldature di riparazione — robusta e affidabile; non richiede gas.",
