 "home_doc_eyebrow": "06 / Esempio di documentazione",
 "home_doc_h2": "Ogni consegna include un <span style=\"color:var(--arc-2)\">dossier</span>: WPS, WPQR, CND, tracciamento.",
 "home_doc_lede": "Non consegniamo solo pezzi — con ogni spedizione consegniamo un dossier documentale completo che dimostra come il pezzo è stato fabbricato, da chi è stato saldato, quale materia prima è stata utilizzata e quali controlli ha superato.",
