 "testim_eyebrow": "02 / La voce delle referenze",
 "testim_h2": "Il feedback dei clienti <span style=\"color:var(--arc-2)\">conferma la qualità dei progetti.</span>",
 "tm1_q": "Era la prima volta che lavoravamo con un fornitore il cui pacchetto documentale arrivava così completo. All'audit in cantiere non è rimasto alcun punto interrogativo — tutte le WPS, i CND e le registrazioni dei materiali erano pronti.",
 "tm1_role": "Responsabile Qualità · OEM energia",
 "tm2_q": "Per la produzione in serie di benne ci aspettavamo sia puntualità sia qualità ripetibile. ArmaWeld mantiene questa disciplina con costanza da tre anni.",
 "tm2_role": "Responsabile Acquisti · OEM macchine pesanti",
 "tm3_q": "Nel nostro progetto di recipienti in pressione abbiamo lavorato con un unico team dalla fase di progettazione alla DoP CE. La messa in servizio è passata senza alcun problema.",
 "tm3_role": "Ingegnere di progetto · Impianto chimico",
