 "sec5_desc": "Per il settore ferroviario: sovrastrutture di veicoli secondo EN 15085 CL1/CL2; per la difesa: strutture blindate resistenti a usura e impatto. In questi ambiti il costo di un singolo cedimento è elevato; per questo si applicano il nostro criterio di accettazione più severo (EN ISO 5817 B) e CND al 100%.",
