 "about_flow_st3_kpi": "WPS · WPQR",
 "about_flow_st4_title": "CND &amp; ispezione",
 "about_flow_st4_sub": "VT · PT · MT · UT · Controllo geometrico",
 "about_flow_st4_kpi": "VT · UT · PT · MT · RT",
 "about_flow_st5_title": "Spedizione",
