 "about_flow_st5_kpi": "Dossier di consegna completo",
 "about_flow_foot_l": "TOTALE 05 STAZIONI",
 "about_flow_foot_r": "● OPERATIVO",
 "quality_cert1_p": "Il quadro di qualità fondamentale per la carpenteria saldata. Comprende la supervisione dell'ingegnere di saldatura, WPS, WPQR, certificazione dei saldatori, piano di ispezione e piena tracciabilità.",
 "quality_cert2_p": "Controllo della produzione in fabbrica (FPC) richiesto per la fabbricazione di strutture portanti in acciaio. EXC3 copre le strutture con elevate conseguenze in caso di cedimento.",
 "quality_cert3_p": "Il nostro quadro gestionale di base, fondato su gestione per processi, orientamento al cliente, approccio basato sul rischio e miglioramento continuo.",
 "quality_cert7_h3": "Sistema di gestione ambientale",
 "quality_cert7_p": "Gestione dei rifiuti, efficienza energetica e delle risorse, controllo degli impatti ambientali. Tutti i rifiuti di taglio, saldatura e trattamento superficiale vengono registrati e smaltiti tramite canali autorizzati.",
 "quality_cert8_h3": "Sistema di gestione della salute e sicurezza sul lavoro",
 "quality_cert8_p": "Valutazione dei rischi, sistemi di permessi di lavoro, gestione dei DPI e audit in sito. Esposizione ai fumi di saldatura, spazi confinati e lavori in quota sono gestiti tramite procedura.",
 "quality_cert4_p1": "<strong style=\"color:var(--bone)\">15614-1</strong> — WPQR per saldatura ad arco di acciai, nichel e leghe di nichel. Procedure approvate per ogni gruppo di materiale da S235 a Strenx 1100, inclusi gli acciai per recipienti in pressione del gruppo P.",
 "quality_cert4_p2": "<strong style=\"color:var(--bone)\">15614-2</strong> — WPQR per saldatura ad arco di alluminio e leghe di alluminio. Giunti testa a testa a piena penetrazione in EN AW-5754 (AlMg3) ed EN AW-6082 (AlSi1MgMn) con TIG (141).",
 "quality_cert5_p1": "<strong style=\"color:var(--bone)\">9606-1</strong> — Qualifica dei saldatori per acciaio e acciaio inox. Abilitazioni distinte per processo (MAG 135, TIG 141, MMA 111), gruppo di materiale, posizione e spessore. Riesame ogni 6 mesi, rinnovo ogni 2 anni.",
 "quality_cert5_p2": "<strong style=\"color:var(--bone)\">9606-2</strong> — Qualifica dei saldatori TIG (141) per leghe di alluminio. Valida per i gruppi FM21 (Al-Mg) e FM22 (Al-Si-Mg) nelle posizioni PA · PB · PF.",
 "quality_cert6_p": "Standard internazionale di qualifica per il personale che esegue, interpreta e referta i controlli CND.",
 "quality_process_lede": "La tracciabilità si perde nel momento in cui manca uno qualsiasi dei sette anelli seguenti. Nel nostro sistema nessun anello può iniziare il lavoro senza la registrazione di quello precedente.",
 "quality_pf1_t": "Ricezione tecnica",
 "quality_pf1_d": "Esame di DWG/DXF/PDF, emissione dell'ordine di lavoro e assegnazione del numero di serie.",
 "quality_pf2_t": "Ricevimento materiale",
 "quality_pf2_d": "Numero di colata + certificato 3.1 + esame visivo. Marcatura della lamiera.",
 "quality_pf3_t": "Taglio e piegatura",
 "quality_pf3_d": "Taglio CNC, controllo dimensionale, verifica dell'angolo di piega. Etichettatura del pezzo.",
 "quality_pf4_t": "Operazione di saldatura",
 "quality_pf4_d": "Saldatore certificato + WPS + registro della temperatura interpass.",
 "quality_pf5_t": "Controlli CND",
 "quality_pf5_d": "Rapporto del personale Livello 2 + criterio di accettazione EN ISO 5817 B.",
 "quality_pf6_t": "Superficie e verniciatura",
 "quality_pf6_d": "Sabbiatura Sa 2½ + ciclo di verniciatura + rapporto di misura DFT.",
 "quality_pf7_t": "Fascicolo documentale",
 "quality_pf7_d": "Tutte le registrazioni consegnate con il prodotto, in formato digitale e cartaceo.",
