 "welding_mig_full": "Saldatura ad arco con filo continuo · ISO 4063 processo 131/135/136",
 "welding_mig_desc": "Processo semiautomatico ad alto deposito con filo alimentato in continuo sotto gas di protezione. La spina dorsale della nostra officina; prima scelta per corpi gru, carpenteria strutturale e telai per movimento terra.",
