 "welding_tig_full": "Saldatura ad arco con elettrodo di tungsteno · ISO 4063 processo 141",
 "welding_tig_desc": "Elettrodo di tungsteno infusibile e argon puro, con materiale d'apporto alimentato a mano — il processo ad arco più pulito e preciso. Prima scelta per serbatoi inox, recipienti in pressione, parti in alluminio, applicazioni sanitarie e saldature a vista.",
