 "welding_tig_con2": "Abilità dell'operatore determinante",
 "welding_tig_con3": "La superficie del materiale deve essere molto pulita",
 "welding_earc_full": "Saldatura ad arco con elettrodo rivestito (SMAW) · ISO 4063 processo 111",
 "welding_earc_desc": "Processo classico con elettrodi rivestiti consumabili; non richiede gas, resiste al vento. Preferito per lavori in cantiere, all'aperto e saldature di riparazione. Con elettrodi basici è adatto anche ai giunti critici che richiedono alta tenacità.",
