 "blog_idx_title": "Blog tecnico — Saldatura e lavorazione dei metalli | ArmaWeld",
 "blog_idx_h1": "Articoli tecnici.",
 "blog_idx_lede": "Note di settore su ingegneria della saldatura, metodi di controllo CND e fabbricazione in acciai ad alta resistenza.",
 "blog_card1_tag": "CND · Controlli non distruttivi",
 "blog_card1_h2": "Cosa sono i CND? Confronto tra i metodi VT, PT, MT, UT, RT",
 "blog_card1_p": "I cinque metodi fondamentali di controllo non distruttivo usati nella carpenteria saldata, quando scegliere ciascuno e i requisiti di certificazione EN ISO 9712.",
 "blog_card1_read": "Leggi l'articolo →",
 "blog_card2_tag": "Acciaio ad alta resistenza",
 "blog_card2_h2": "Parametri di saldatura dell'S960QL: preriscaldo, apporto termico e WPS",
 "blog_card2_p": "I parametri critici per saldare l'acciaio ad altissima resistenza S960QL: calcolo del CEV, materiale d'apporto H5 obbligatorio e controllo della temperatura interpass.",
 "blog_card2_read": "Leggi l'articolo →",
 "blog_card3_tag": "Norme e certificazione",
 "blog_card3_h2": "Cos'è la EN 1090 EXC3? Guida alla marcatura CE delle strutture in acciaio",
 "blog_card3_p": "La differenza tra EN 1090-1 ed EN 1090-2, le classi di esecuzione EXC1–EXC4 e i passaggi necessari per ottenere la certificazione CE.",
 "blog_card3_read": "Leggi l'articolo →",
 "blog_ndt_title": "Cosa sono i CND? Confronto VT, PT, MT, UT, RT | ArmaWeld Blog",
 "blog_ndt_tag": "CND · Controlli non distruttivi",
 "blog_ndt_h1": "Cosa sono i CND? Confronto tra VT, PT, MT, UT, RT",
 "blog_ndt_read": "8 min di lettura",
 "blog_ndt_author": "ArmaWeld Engineering",
 "blog_ndt_breadcrumb3": "Metodi CND",
 "blog_ndt_s0": "<p>I controlli non distruttivi (CND) sono il metodo per verificare l'integrità del materiale di strutture saldate, attrezzature a pressione e costruzioni portanti senza distruggere il pezzo. La EN ISO 9712 è il documento di riferimento internazionale che definisce i requisiti di certificazione del personale CND.</p><p>La scelta del metodo CND nella carpenteria saldata è determinata dal tipo di materiale, dalla geometria del pezzo, dal tipo di difetto atteso e dalla norma applicabile.</p>",
 "blog_ndt_s1": "<h2>I cinque metodi CND fondamentali</h2><table class=\"comparison-table\"><thead><tr><th>Metodo</th><th>Nome completo</th><th>Rileva</th><th>Limiti</th></tr></thead><tbody><tr><td>VT</td><td>Esame visivo</td><td>Cricche superficiali, porosità, sovrametallo eccessivo, difetti di geometria del cordone</td><td>Solo superficie; i difetti interni non sono visibili</td></tr><tr><td>PT</td><td>Liquidi penetranti</td><td>Cricche affioranti, porosità, sfogliature</td><td>Solo difetti aperti in superficie; non utilizzabile su materiali porosi</td></tr><tr><td>MT</td><td>Particelle magnetiche</td><td>Cricche e ripiegature superficiali e sub-superficiali (≤3 mm)</td><td>Solo materiali ferromagnetici; non funziona su alluminio o acciaio inox</td></tr><tr><td>UT</td><td>Controllo ultrasonoro</td><td>Cricche interne, difetti di fusione, sfogliature, cavità</td><td>Difetti interni profondi in materiali spessi; interpretazione dipendente dall'operatore</td></tr><tr><td>RT</td><td>Controllo radiografico</td><td>Porosità interne, inclusioni di scoria, incisioni marginali, mancanza di fusione</td><td>Richiede licenza per radiazioni; orientamento della cricca determinante; accesso da entrambi i lati</td></tr></tbody></table>",
 "blog_ndt_s2": "<h2>VT — Esame visivo</h2><p>Il <strong>VT (esame visivo)</strong> è il primo passo di tutti i controlli CND e viene eseguito secondo la EN ISO 17637. Si valutano geometria del cordone, rugosità superficiale, spruzzi, colorazioni e cricche visibili a occhio.</p><p>Il VT deve sempre essere eseguito prima degli altri metodi CND. Una saldatura che verrebbe respinta visivamente non viene sottoposta a PT o UT — con risparmio di tempo e di costi.</p><div class=\"callout\"><p><strong>Criteri di accettazione EN ISO 5817:</strong> le dimensioni ammissibili dei difetti sono definite in base al livello di qualità della saldatura B, C o D. Il livello di qualità B è generalmente applicabile secondo EN 1090 EXC3.</p></div>",
 "blog_ndt_s3": "<h2>PT — Liquidi penetranti</h2><p>Il <strong>PT (controllo con liquidi penetranti)</strong> viene applicato secondo la EN ISO 3452-1. Si usano liquidi penetranti fluorescenti o colorati (rosso-bianco) per rilevare le discontinuità affioranti in superficie.</p><p>Fasi di applicazione:</p><ol><li>Pulizia della superficie (rimozione di olio, ruggine e vernice)</li><li>Applicazione del penetrante e tempo di penetrazione (tipicamente 10–30 min)</li><li>Rimozione del penetrante in eccesso</li><li>Applicazione del rivelatore</li><li>Valutazione visiva (luce UV o bianca)</li></ol><p>Il PT è il metodo di controllo superficiale preferito per le strutture in alluminio, dove l'MT non è applicabile.</p>",
 "blog_ndt_s4": "<h2>MT — Particelle magnetiche</h2><p>L'<strong>MT (controllo con particelle magnetiche)</strong> viene eseguito secondo la EN ISO 17638. Nei materiali ferromagnetici (acciaio al carbonio, acciaio basso legato) si genera un campo magnetico e la polvere di ferro o le particelle fluorescenti si concentrano sopra i difetti.</p><p><strong>Vantaggio:</strong> le cricche sub-superficiali (profondità ≤3 mm) vengono rilevate in modo molto più affidabile rispetto al PT. L'MT è frequentemente richiesto per giunti a T e saldature d'angolo secondo EN 1090 EXC3.</p><div class=\"callout\"><p><strong>Nota:</strong> l'MT non è applicabile all'acciaio inox austenitico né all'alluminio. Per il controllo superficiale di questi materiali si usa il <strong>PT</strong>.</p></div>",
 "blog_ndt_s5": "<h2>UT — Controllo ultrasonoro</h2><p>L'<strong>UT (controllo ultrasonoro)</strong> viene eseguito secondo la EN ISO 11666. Onde sonore ad alta frequenza vengono trasmesse attraverso il materiale; le riflessioni causate dai difetti interni vengono valutate per determinare posizione e dimensione del difetto.</p><p>Le moderne tecniche <span class=\"tag-inline\">TOFD</span> (Time-of-Flight Diffraction) e <span class=\"tag-inline\">Phased Array UT (PAUT)</span> offrono un'affidabilità e una registrabilità nettamente superiori rispetto all'UT convenzionale. Particolarmente preferite per le saldature di recipienti in pressione e condotte.</p>",
 "blog_ndt_s6": "<h2>RT — Controllo radiografico</h2><p>L'<strong>RT (controllo radiografico)</strong> viene eseguito secondo la EN ISO 17636-1. Raggi X o raggi gamma attraversano la sezione della saldatura per formare un'immagine su pellicola o su un rivelatore digitale.</p><p>L'RT mostra molto chiaramente i difetti volumetrici come porosità e inclusioni di scoria, ma è meno affidabile dell'UT nel rilevare le cricche planari — perché una cricca può non essere rilevata se il suo orientamento è parallelo alla direzione del fascio.</p>",
 "blog_ndt_s7": "<h2>Livelli di certificazione EN ISO 9712</h2><p>Il personale CND è certificato su tre livelli secondo la EN ISO 9712:</p><ul><li><strong>Livello 1:</strong> esegue i controlli secondo una procedura definita; non redige rapporti in autonomia. Lavora sotto la supervisione di personale esperto.</li><li><strong>Livello 2:</strong> prepara le procedure, esegue i controlli, valuta i risultati secondo la norma e redige i rapporti. Lo standard di settore per gli ispettori operativi.</li><li><strong>Livello 3:</strong> definisce il sistema CND, approva procedure e istruzioni tecniche, esamina il personale di Livello 1 e 2. Autorità di livello ingegneristico.</li></ul><p>In ArmaWeld i controlli VT, PT, MT e UT sono eseguiti dal nostro personale interno <strong>certificato EN ISO 9712 Livello 2</strong>. I servizi RT sono forniti tramite il nostro laboratorio partner accreditato.</p>",
 "blog_ndt_cta_h3": "Richieda informazioni sui servizi CND",
 "blog_ndt_cta_p": "Contatti il nostro team tecnico per stabilire quale metodo CND richiede il Suo progetto.",
