 "blog_wps_title": "Cos'è la WPS? Guida alla specifica di procedura di saldatura | ArmaWeld Blog",
 "blog_wps_meta_desc": "La base normativa di una WPS, i suoi contenuti, la relazione con il WPQR e il processo di qualifica secondo EN ISO 15614-1. Portfolio WPS ArmaWeld.",
 "blog_wps_og_title": "Cos'è la WPS? Guida alla specifica di procedura di saldatura | ArmaWeld",
 "blog_wps_tag": "Norme e certificazioni",
 "blog_wps_h1": "Cos'è la WPS? Guida alla specifica di procedura di saldatura",
 "blog_wps_read": "9 min di lettura",
 "blog_wps_author": "ArmaWeld Engineering",
 "blog_wps_breadcrumb3": "Cos'è la WPS?",
 "blog_wps_s0": "<p>La specifica di procedura di saldatura (WPS) è il documento tecnico che definisce come deve essere eseguito un determinato giunto saldato. I parametri che contiene — processo, gruppo di materiale, campo di spessore, posizione di saldatura, materiale d'apporto, gas di protezione, temperatura di preriscaldo e interpass — costituiscono il quadro a cui il saldatore deve attenersi durante la produzione.</p><p>La WPS è obbligatoria in ogni produzione eseguita secondo EN ISO 3834-2 ed EN 1090 EXC2/3/4. Saldare con una WPS non approvata può invalidare la certificazione della struttura e la marcatura CE.</p>",
 "blog_wps_s1": "<h2>Base normativa della WPS</h2><p>L'obbligo della WPS deriva da più norme:</p><ul><li><span class=\"tag-inline\">EN ISO 3834-2</span> — Nell'ambito dei requisiti di qualità estesi, una WPS approvata è obbligatoria.</li><li><span class=\"tag-inline\">EN 1090-2</span> — Una WPS è richiesta per ogni processo di saldatura nelle classi di esecuzione EXC2 e superiori.</li><li><span class=\"tag-inline\">EN 13445</span> — Sui recipienti a pressione non può essere eseguita alcuna saldatura senza la coppia WPS + WPQR.</li><li><span class=\"tag-inline\">PED 2014/68/UE</span> — L'approvazione della procedura di saldatura è obbligatoria per le attrezzature a pressione di categoria II e superiore.</li></ul><p>La WPS non è quindi una semplice regola: è il fondamento tecnico che dimostra l'affidabilità della struttura.</p>",
 "blog_wps_s2": "<h2>Cosa contiene una WPS?</h2><table class=\"data-table\"><thead><tr><th>Sezione</th><th>Contenuto</th></tr></thead><tbody><tr><td>Informazioni generali</td><td>Numero WPS, revisione, riferimento WPQR, ingegnere redattore</td></tr><tr><td>Metallo base</td><td>Norma del materiale, gruppo di acciaio (ISO/TR 15608), campo di spessore</td></tr><tr><td>Processo di saldatura</td><td>Codice del processo (es. 135 MAG, 141 TIG), passata singola/multipla, posizione di saldatura</td></tr><tr><td>Materiale d'apporto</td><td>Norma, classificazione, diametro, classe di idrogeno diffusibile (H5 ecc.)</td></tr><tr><td>Gas di protezione</td><td>Composizione (Ar/CO₂ %), portata (l/min)</td></tr><tr><td>Parametri elettrici</td><td>Corrente (A), tensione (V), polarità, velocità di avanzamento (cm/min), apporto termico (kJ/mm)</td></tr><tr><td>Condizioni termiche</td><td>Temperatura di preriscaldo (°C), temperatura interpass max. (°C), PWHT</td></tr><tr><td>Preparazione del giunto</td><td>Tipo di giunto, angolo del cianfrino, distanza al vertice, spalla</td></tr></tbody></table>",
 "blog_wps_s3": "<h2>Relazione con il WPQR</h2><p>Una WPS deve basarsi su un <strong>WPQR (verbale di qualifica della procedura di saldatura)</strong>, un documento convalidato sperimentalmente. La sequenza è la seguente:</p><ol><li>Si redige la <strong>pWPS (WPS preliminare)</strong> — una bozza dell'ingegnere basata sulle conoscenze tecniche.</li><li>Si esegue la <strong>saldatura di qualifica</strong> — con provini per le prove distruttive.</li><li>Si eseguono le <strong>prove distruttive</strong> — trazione, piegamento, durezza, Charpy, macro.</li><li>Si redige il <strong>WPQR</strong> — firmato da un organismo di approvazione indipendente (ON o laboratorio accreditato).</li><li>La <strong>WPS</strong> viene approvata con riferimento al WPQR e utilizzata in produzione.</li></ol><div class=\"callout\"><p><strong>Importante:</strong> il campo di validità della WPS deriva dalle condizioni di prova del WPQR. Ad esempio, un WPQR eseguito su 12 mm può coprire un campo di 6–24 mm; tuttavia non copre i 25 mm.</p></div>",
 "blog_wps_s4": "<h2>Portfolio WPS di ArmaWeld</h2><p>ArmaWeld dispone di un'ampia libreria di WPS approvate secondo EN ISO 15614-1 (acciaio) ed EN ISO 15614-2 (alluminio). Questa libreria copre i seguenti gruppi di materiali: acciai strutturali S235–S960QL e Strenx 700/900/960/1100, acciai per recipienti a pressione P265GH/P355NH, acciai inossidabili austenitici 304L/316L, acciai antiusura HARDOX 400/450/500 e leghe di alluminio EN AW-5754/6082. All'avvio di ogni nuovo progetto, l'ingegnere di saldatura verifica l'applicabilità della WPS; se il campo di validità viene superato, si avvia un nuovo iter di pWPS e WPQR.</p>",
 "blog_wps_cta_h3": "Consultate il nostro portfolio WPS",
 "blog_wps_cta_p": "Comunicateci materiale e campo di spessore del vostro progetto; risponderemo entro 48 ore con la WPS approvata applicabile.",
