 "home_persona_eyebrow": "01 / A chi si rivolge",
 "home_persona_h2": "Un processo chiaro per <span style=\"color:var(--arc-2)\">i decisori tecnici.</span>",
 "home_persona1_t": "Acquisti / Supply chain",
 "home_persona1_d": "Preventivi in 48 ore, MOQ flessibile e tempi di consegna chiari — vedete impegni sul processo, non solo il prezzo.",
 "home_persona1_l": "Processo di preventivo →",
 "home_persona2_t": "Qualità e conformità",
 "home_persona2_d": "WPS, WPQR, registrazioni CND e certificati dei materiali nel dossier di consegna — nessuna lacuna in audit.",
 "home_persona2_l": "Pacchetto documentale →",
 "home_persona3_t": "Ingegneria di progetto / di produzione",
 "home_persona3_d": "Processo di saldatura, apporto termico e piano delle tolleranze sono fissati in fase di preventivo — meno sorprese in officina.",
 "home_persona3_l": "Piano di produzione →",
 "home_aud_eyebrow": "02 / Chi serviamo",
 "home_aud_h2": "OEM, EPC e <span style=\"color:var(--arc-2)\">partner di carpenteria.</span>",
 "home_aud1_t": "OEM di macchine e attrezzature",
 "home_aud1_d": "Carpenteria metallica saldata di serie e prototipale per casse, benne, bracci e parti soggette a usura.",
 "home_aud2_t": "Impianti energetici e di processo",
 "home_aud2_d": "Recipienti a pressione, piattaforme e strutture in acciaio — produzione documentata secondo PED ed EN 1090.",
 "home_aud3_t": "Imprese di costruzioni e infrastrutture",
 "home_aud3_d": "Carpenteria metallica EXC3, supporto al montaggio e kit di pezzi pronti per il cantiere.",
 "home_blog_eyebrow": "08 / Approfondimenti tecnici",
 "home_blog_h2": "Note di <span style=\"color:var(--arc-2)\">ingegneria della saldatura.</span>",
 "home_blog1_t": "Cosa sono WPS e WPQR?",
 "home_blog1_d": "Una saldatura senza procedura approvata — il primo punto di non conformità in audit.",
 "home_blog2_t": "EN 1090 EXC3 nella pratica",
 "home_blog2_d": "Cosa richiedono davvero il controllo della produzione, la tracciabilità e il dossier CE.",
 "home_blog3_t": "Metodi CND — guida breve",
 "home_blog3_d": "VT, PT, MT, UT — quale metodo per quale difetto.",
 "home_certs_eyebrow": "09 / Certificazioni",
 "home_certs_h2": "La <span style=\"color:var(--arc-2)\">spina dorsale documentale</span> di una produzione verificabile.",
 "home_certs_lede": "Ogni progetto si basa su WPS approvate, personale certificato e registrazioni di qualità tracciabili. Le norme riportate di seguito sono mantenute attivamente.",
 "home_certs_link": "Processo qualità e pacchetto documentale →",
 "proj1_outcome": "Produzione di benne in serie con WPS ripetibile e piano VT/MT per singolo pezzo.",
 "proj2_outcome": "Struttura principale di magazzino con dossier EXC2/EXC3 e rapporto dimensionale.",
 "proj3_outcome": "Reattore secondo PED con WPS TIG/MIG, RT 100% e dossier CE.",
 "proj4_outcome": "Struttura fotovoltaica con zincatura a caldo, controllo delle tolleranze di taglio e supporto al montaggio.",
 "proj5_outcome": "Telaio carrello ferroviario con catena di registrazioni EN 15085 CL1 e UT 100%.",
 "proj6_outcome": "Piattaforma, scale e parapetti — consegnati con distinta di montaggio e preparazione superficiale.",
 "services_s01_benefit": "Ogni saldatura registrata con WPS approvata.",
 "services_s02_benefit": "Bordi pronti per la saldatura e controllo delle tolleranze.",
 "services_s03_benefit": "Accoppiamento in montaggio garantito dalla simulazione di piegatura.",
 "why_eyebrow": "07 / Perché ArmaWeld",
 "why_h2": "Disciplina di procedura, <span style=\"color:var(--arc-2)\">non marketing.</span>",
 "why1_t": "Quadro EN ISO 3834-2",
 "why1_d": "La gestione della qualità in saldatura è routine quotidiana — non una modalità speciale per i progetti.",
 "why2_t": "Carpenteria metallica EXC3",
 "why2_d": "Controllo della produzione, tracciabilità e dossier CE da un'unica catena di dati.",
 "why3_t": "4 metodi CND in-house",
 "why3_d": "VT, PT, MT, UT — personale di livello 2; RT tramite partner quando richiesto.",
 "why4_t": "SLA di preventivo in 48 ore",
 "why4_d": "Scelte di materiali e procedure messe per iscritto nel preventivo — non promesse verbali.",
 "footer_capability": "EN ISO 3834-2 · EN 1090 EXC3 · 4 metodi CND · preventivo in 48 ore",
 "cap_title_tag": "Capacità produttiva — ArmaWeld | EN 1090 EXC3 · EN ISO 3834-2",
 "cap_meta_desc": "Capacità produttiva ArmaWeld: carpenteria EN 1090 EXC3, qualità in saldatura EN ISO 3834-2, gruppi di materiali, CND e preventivi in 48 ore. Stabilimento di Konya.",
 "cap_h1": "Capacità produttiva<br/><span class=\"arc\">Konya · sito integrato</span>",
 "cap_updated": "Ultimo aggiornamento: maggio 2026",
 "cap_intro": "Questa pagina riassume ciò che produciamo realmente nel nostro stabilimento di Konya. Condividiamo certificati, ambito di materiali/processi e flussi di lavoro dal preventivo alla consegna — non un elenco gonfiato di macchinari.",
 "cap_cert_h": "Certificati e ambito",
 "cap_cert_p": "EN 1090-2 EXC3 (carpenteria metallica), EN ISO 3834-2 (qualità in saldatura), ISO 9001:2015 (qualità), ISO 14001:2015 (ambiente), ISO 45001:2018 (salute e sicurezza sul lavoro). Libreria WPS basata su WPQR; saldatori EN ISO 9606-1/2. Personale CND EN ISO 9712 livello 2.",
 "cap_mat_h": "Gruppi di materiali",
 "cap_mat_p": "S235–S960QL, acciai antiusura Strenx/HARDOX, S700MC, inox 304/316L e leghe di alluminio selezionate — WPS approvate e controllo del calore per ogni gruppo.",
 "cap_proc_h": "Processi",
 "cap_proc_p": "MIG/MAG, TIG, SMAW; taglio plasma/laser/cesoia CNC; piegatura con pressa piegatrice; assemblaggio meccanico. VT, PT, MT, UT sulle saldature critiche; RT tramite laboratorio partner.",
 "cap_sla_h": "Preventivo e consegna",
 "cap_sla_p": "Preventivo scritto in media entro 48 ore dall'esame del disegno: materiale, sintesi WPS, piano CND e tempi di consegna. NDA standard; coordinamento delle spedizioni per l'export disponibile.",
 "cap_contact_h": "Inviate i file tecnici",
 "cap_contact_p": "Utilizzate il modulo di contatto o info@armaweld.com con DWG/DXF/PDF e informazioni sul materiale — l'ufficio tecnico risponde entro 48 ore.",
 "footer_cap_link": "Profilo di capacità →",
 "services_cta_p": "Inviateci i disegni o un campione — prepareremo l'analisi dei costi e un piano di produzione entro 48 ore.",
 "footer_legal": "Contenuti, immagini e marchi presenti su questo sito web sono di proprietà di ArmaWeld. La riproduzione o l'utilizzo senza autorizzazione sono vietati.",
 "home_ref_q1": "I fornitori precedenti che saldavano l'S960QL saltavano il preriscaldo — avevamo cricche. In ArmaWeld la WPS e il protocollo di preriscaldo erano completi.",
 "home_ref_q1_who": "RESP. ACQUISTI · OEM VEICOLI PESANTI",
 "home_ref_q2": "Abbiamo richiesto il pacchetto documentale EN 1090 EXC3. Dossier CE, elenco WPQR, registrazioni CND — tutto pronto alla prima consegna.",
 "home_ref_q2_who": "INGEGNERE QUALITÀ · IMPIANTO ENERGETICO",
 "home_ref_q3": "Da tre anni ordiniamo benne in serie ogni anno. La variazione di qualità tra un pezzo e l'altro è quasi nulla — una disciplina difficile da mantenere.",
 "home_ref_q3_who": "DIRETTORE GENERALE · COSTRUZIONE DI MACCHINE",
