 "saw35_s5_d": "Travi a I saldate e colonne scatolate",
 "saw35_s6_t": "Serbatoi e recipienti in pressione",
 "saw35_s6_d": "Cordoni longitudinali dei mantelli",
 "saw35_faq_label": "FAQ",
 "saw35_faq_h2": "FAQ sulla saldatura ad arco sommerso",
 "saw35_q1": "Che cos'è la saldatura ad arco sommerso?",
 "saw35_a1": "La saldatura ad arco sommerso (SAW, ISO 4063-121) è un processo ad arco automatizzato in cui l'arco tra un filo alimentato in continuo e il pezzo scocca sotto un flusso granulare. Il flusso protegge l'arco e il bagno di fusione e garantisce alta deposizione e penetrazione profonda.",
 "saw35_q2": "Che cosa offre un impianto SAW da 35 m?",
 "saw35_a2": "I particolari lunghi possono essere saldati in un unico piazzamento. Velocità e parametri restano costanti lungo il cordone, quindi la qualità è ripetibile, i punti di arresto-ripartenza e il relativo rischio di difetti diminuiscono e i tempi di riposizionamento si riducono.",
 "saw35_q3": "Quali particolari sono adatti alla saldatura ad arco sommerso?",
 "saw35_a3": "Particolari in acciaio di medio e grande spessore con cordoni lunghi e rettilinei saldabili in piano (PA) o ad angolo frontale (PB): bracci, longheroni di telai, travi a I saldate, colonne scatolate, giunti testa a testa di lamiere e mantelli di serbatoi. Per cordoni molto corti e lamiere sottili il MAG è la scelta migliore.",
 "saw35_q4": "Offrite la saldatura SAW conto terzi?",
 "saw35_a4": "Sì. Saldiamo bracci, telai e particolari a cordone lungo per i vostri prodotti secondo i vostri disegni. I particolari possono arrivare per la sola saldatura oppure essere quotati come fabbricazione completa, inclusi taglio, piegatura, saldatura e CND.",
 "saw35_q5": "Di cosa avete bisogno per un preventivo?",
 "saw35_a5": "Un disegno (PDF/DXF/STEP), qualità e spessore del materiale, lunghezze dei cordoni, quantità e, se presenti, la classe di qualità (EN 1090 EXC, EN ISO 5817) e i requisiti CND.",
 "saw35_blog_label": "Guide tecniche",
 "saw35_cta_h2": "Esaminiamo insieme i vostri particolari a cordone lungo",
 "saw35_cta_p": "Inviateci il disegno del vostro braccio, telaio o particolare a cordone lineare e prepareremo un preventivo per la saldatura ad arco sommerso.",
 "saw35_cta_services": "Tutti i servizi",
 "saw35_rel1": "Impianti di saldatura ad arco sommerso per bracci, telai e cordoni lunghi",
