 "deep_saw_35m_html": "<p class=\"deep-note\"><strong>Impianto di saldatura ad arco sommerso da 35 m:</strong> cordoni lineari lunghi, bracci di macchine e gru, telai di rimorchi e macchine vengono saldati in un unico piazzamento. <a href=\"tozalti-kaynak.html\">Servizio di saldatura ad arco sommerso →</a></p>",
 "services_saw_benefit": "Un unico piazzamento per i particolari lunghi, cordoni ripetibili e meno difetti da arresto-ripartenza.",
