 "kf_label": "Konya, Turchia · Produzione in subfornitura",
 "kf_h1": "Servizi di <span>saldatura conto terzi</span><br>a Konya",
 "kf_lead": "Carpenteria metallica saldata in subfornitura da Konya con produzione certificata EN 1090 e ISO 3834-2. Saldatura MIG/MAG, TIG e robotizzata per OEM.",
