 "kf_s1_label": "Servizi di saldatura conto terzi",
 "kf_s1_title": "Carpenteria metallica saldata in subfornitura da Konya",
 "kf_s1_desc": "La produzione in serie o a lotti viene eseguita secondo i disegni e le specifiche del cliente OEM. Ogni processo è documentato e certificato.",
 "kf_c1_icon": "MIG / MAG",
 "kf_c1_h": "Saldatura MIG/MAG",
 "kf_c1_p": "Produzione conto terzi in acciai al carbonio, inox e ad alta resistenza con WPS approvate e saldatori qualificati EN ISO 9606-1.",
 "kf_c2_icon": "TIG",
 "kf_c2_h": "Saldatura TIG",
 "kf_c2_p": "TIG DC/AC per acciaio inox e alluminio. Apporto termico controllato per tubazioni e particolari a parete sottile.",
 "kf_c3_icon": "Taglio",
 "kf_c3_h": "Taglio e preparazione",
 "kf_c3_p": "Taglio plasma CNC, laser e di profilati, dal DXF al particolare pronto per la saldatura. Preparazione in tolleranza, cianfrini inclusi.",
 "kf_c4_icon": "Piegatura",
 "kf_c4_h": "Piegatura CNC",
 "kf_c4_p": "Piegatura a V/U e calandratura di lamiere. Angoli programmati, compensazione del ritorno elastico e pianificazione del processo orientata all'accoppiamento in assemblaggio.",
 "kf_c5_icon": "Assemblaggio",
 "kf_c5_h": "Assemblaggio meccanico",
 "kf_c5_p": "Assemblaggio dei particolari conto terzi, controllo della coppia di serraggio e imballaggio pronto per il cantiere.",
 "kf_c6_icon": "CND / Qualità",
 "kf_c6_h": "Qualità e CND",
 "kf_c6_p": "VT, PT, MT e UT in-house. Procedure, qualifica dei saldatori e dossier di consegna secondo ISO 3834-2.",
 "kf_s2_label": "Ambito produttivo",
 "kf_s2_title": "Capacità di processo",
 "kf_s2_desc": "Dal nostro stabilimento di Konya i clienti conto terzi ricevono un servizio integrato dal taglio al dossier di consegna. Condividiamo l'ambito di certificazioni e procedure piuttosto che il numero di macchine.",
 "kf_th1": "Area",
