 "kf_s3_title": "Come lavoriamo",
 "kf_st1_h": "Accordo tecnico",
 "kf_st1_p": "Approvazione di disegni, tolleranze e distinta base. È possibile firmare un NDA.",
 "kf_st2_h": "Campione e FAI",
 "kf_st2_p": "First Article Inspection. La produzione in serie non parte senza l'approvazione del cliente.",
 "kf_st3_h": "Produzione in serie",
 "kf_st3_p": "Pianificazione dei lotti settimanale o mensile. Sono disponibili opzioni di consegna a stock e JIT.",
 "kf_st4_h": "Registrazioni qualità e consegna",
