 "pt_how_eyebrow": "01 / Come funziona",
 "pt_how_h2": "Non traffico telefonico, ma <span class=\"arc\">un'unica fonte di verità.</span>",
 "pt_screens_eyebrow": "02 / Il portale, schermata per schermata",
 "pt_screens_h2": "Cosa <span class=\"arc\">vedrete nel portale?</span>",
 "pt_roles_eyebrow": "03 / Chi ottiene cosa",
 "pt_roles_h2": "Una sola registrazione, <span class=\"arc\">tre team diversi.</span>",
 "pt_sec_h": "Sicurezza e riservatezza",
 "pt_cta_h2": "Il vostro account sul portale si apre con il primo ordine.",
 "pt_cta_p": "Inviate il vostro disegno tecnico e ricevete entro 48 ore un preventivo completo, con processo di saldatura, WPS e piano CND.",
