 "pt_how1_h": "Viene aperto il vostro account",
 "pt_how1_p": "Quando approvate il preventivo, viene configurato un account sul portale per la vostra azienda; i colleghi vengono aggiunti con accessi basati sui ruoli.",
 "pt_how2_h": "I dati di produzione confluiscono nel portale",
 "pt_how2_p": "Ogni ordine di lavoro viene aperto con un numero di serie digitale; registrazioni di materiale, WPS, saldatore, CND e dimensionali arrivano nel portale durante la produzione.",
 "pt_how3_h": "Voi seguite l'avanzamento",
 "pt_how3_p": "La posizione del vostro ordine sulla linea a 7 fasi, la consegna stimata e l'eventuale rischio di ritardo sono visibili con settimane di anticipo, non il giorno della spedizione.",
 "pt_how4_h": "Il fascicolo resta a disposizione",
 "pt_how4_p": "Dopo la consegna, il fascicolo qualità completo e le registrazioni post-vendita restano in archivio, pronti da presentare con un clic durante un audit.",
 "pt_role1_h": "Acquisti",
 "pt_role1_p": "Individua per tempo i rischi sui tempi di consegna e pianifica su dati reali, senza telefonate per chiedere lo stato dell'ordine.",
 "pt_role2_h": "Qualità / Ingegneria",
 "pt_role2_p": "Esamina e approva WPS, CND e rapporti dimensionali prima della spedizione; i documenti mancanti emergono prima della consegna.",
 "pt_role3_h": "Direzione / Audit",
 "pt_role3_p": "Gestisce il fornitore sulla base di evidenze; presenta i documenti dall'archivio con un clic durante gli audit.",
 "pt_sec1": "Connessione cifrata TLS",
 "pt_sec2": "Accessi basati sui ruoli",
 "pt_sec3": "Backup periodici",
 "pt_sec4": "Coperto da accordo di riservatezza",
 "pt_s_panel_h": "Dashboard",
 "pt_s_panel_p": "Appena effettuato l'accesso, avete davanti una sintesi di tutti i vostri ordini.",
 "pt_s_panel_list": "<ul><li>Numero di ordini in produzione, pronti per la spedizione, completati e totali</li><li>Elenco “Azione richiesta”: voci in attesa della vostra approvazione e conferme di consegna</li><li>Da ogni scheda, un clic per raggiungere l'ordine corrispondente</li></ul>",
 "pt_s_panel_alt": "Schermata del portale clienti ArmaWeld: Dashboard",
 "pt_img_panel": "/assets/portal/en/panel.jpg?r=3",
 "pt_s_takip_h": "Prestazioni di consegna e tracciamento ordini in tempo reale",
 "pt_s_takip_p": "Le fasi di produzione dei vostri ordini attivi vengono mostrate in tempo reale su una linea con codice colore.",
 "pt_s_takip_list": "<ul><li>Tasso di puntualità delle consegne, avanzamento medio della produzione e consegne imminenti</li><li>Una linea a 7 fasi per ogni ordine: fasi completate, in corso e in attesa</li><li>Stati in produzione, completato e annullato a colpo d'occhio</li></ul>",
 "pt_s_takip_alt": "Schermata del portale clienti ArmaWeld: Prestazioni di consegna e tracciamento ordini in tempo reale",
 "pt_img_takip": "/assets/portal/en/takip.jpg?r=3",
 "pt_s_siparisler_h": "I miei ordini",
 "pt_s_siparisler_p": "Tutti i vostri ordini in un unico elenco; ricerca per numero d'ordine, titolo o materiale.",
 "pt_s_siparisler_list": "<ul><li>Numero d'ordine e di serie, titolo e qualità del materiale</li><li>Stato e fase, ad es. “6/7 — Trattamento superficiale / verniciatura”, con barra di avanzamento</li><li>Data di consegna e link al dettaglio dell'ordine</li></ul>",
 "pt_s_siparisler_alt": "Schermata del portale clienti ArmaWeld: I miei ordini",
 "pt_img_siparisler": "/assets/portal/en/siparisler.jpg?r=3",
 "pt_s_izlenebilirlik_h": "Cronologia di tracciabilità",
 "pt_s_izlenebilirlik_p": "Nel dettaglio dell'ordine, ogni fase è registrata insieme a chi l'ha eseguita e quando.",
 "pt_s_izlenebilirlik_list": "<ul><li>Operatore, data e note in ogni fase</li><li>Il numero di WPS utilizzato nella fase di saldatura</li><li>Documenti di fase (rapporto dimensionale, WPS, qualifica del saldatore): consultazione o download</li></ul>",
 "pt_s_izlenebilirlik_alt": "Schermata del portale clienti ArmaWeld: Cronologia di tracciabilità",
 "pt_img_izlenebilirlik": "/assets/portal/en/izlenebilirlik.jpg?r=3",
 "pt_s_belgeler_h": "Documenti di qualità",
 "pt_s_belgeler_p": "Tutti i documenti tecnici e i certificati dei vostri ordini in un unico archivio.",
 "pt_s_belgeler_list": "<ul><li>WPS, WPQR, certificati dei materiali EN 10204 3.1, rapporti CND, patentini dei saldatori, rapporti di controllo in accettazione e dimensionali</li><li>Filtro per ordine</li><li>Consultazione e download come PDF firmati</li></ul>",
 "pt_s_belgeler_alt": "Schermata del portale clienti ArmaWeld: Documenti di qualità",
 "pt_img_belgeler": "/assets/portal/en/belgeler.jpg?r=3",
 "pt_s_mesajlar_h": "Messaggistica per ordine",
 "pt_s_mesajlar_p": "Le vostre conversazioni con il team ArmaWeld restano collegate alla commessa invece di perdersi nei thread di e-mail.",
 "pt_s_mesajlar_list": "<ul><li>Ogni conversazione collegata a un ordine e a un argomento</li><li>Ricerca per oggetto o numero d'ordine, filtro dei messaggi non letti</li><li>Allegati in formato PDF, immagine, Word ed Excel</li></ul>",
 "pt_s_mesajlar_alt": "Schermata del portale clienti ArmaWeld: Messaggistica per ordine",
 "pt_img_mesajlar": "/assets/portal/en/mesajlar.jpg?r=3",
 "pt_s_bildirimler_h": "Notifiche di fase e di documento",
 "pt_s_bildirimler_p": "Venite informati quando una fase del vostro ordine viene completata o viene aggiunto un nuovo documento.",
 "pt_s_bildirimler_list": "<ul><li>Notifiche “Fase aggiornata” e notifiche di documento</li><li>Conteggio dei non letti e funzione segna tutti come letti</li><li>Dalla notifica direttamente alla pagina dell'ordine</li></ul>",
 "pt_s_bildirimler_alt": "Schermata del portale clienti ArmaWeld: Notifiche di fase e di documento",
 "pt_img_bildirimler": "/assets/portal/en/bildirimler.jpg?r=3",
 "pt_s_teklif_h": "Richieste di preventivo dal portale (RFQ)",
 "pt_s_teklif_p": "Aprite richieste di preventivo per nuovi progetti nel portale e seguite l'iter in tempo reale.",
 "pt_s_teklif_list": "<ul><li>Nuova richiesta caricando DWG / DXF / PDF</li><li>Stato della richiesta: in attesa, preventivata, convertita in ordine, rifiutata</li><li>Storico delle richieste con date di invio e date obiettivo</li></ul>",
 "pt_s_teklif_alt": "Schermata del portale clienti ArmaWeld: Richieste di preventivo dal portale (RFQ)",
 "pt_img_teklif": "/assets/portal/en/teklif.jpg?r=3",
 "pt_s_satis_sonrasi_h": "Post-vendita",
 "pt_s_satis_sonrasi_p": "I prodotti consegnati restano tracciati nel portale anche dopo la consegna.",
 "pt_s_satis_sonrasi_list": "<ul><li>Prodotti installati con numeri di serie, garanzie attive</li><li>Richieste di garanzia e assistenza, monitoraggio della manutenzione</li><li>Richieste di ricambi</li></ul>",
 "pt_s_satis_sonrasi_alt": "Schermata del portale clienti ArmaWeld: Post-vendita",
 "pt_img_satis_sonrasi": "/assets/portal/en/satis-sonrasi.jpg?r=3",
